#include <algorithm>
#include <iostream>
#include <vector>

struct Range { long long lo, hi; };

/* Sort by start, then sweep: an interval either extends the one being
   built or starts a new one. Touching counts as overlapping. */
static std::vector<Range> merge(std::vector<Range> v) {
    std::sort(v.begin(), v.end(),
              [](const Range& a, const Range& b) {
                  return a.lo != b.lo ? a.lo < b.lo : a.hi < b.hi;
              });
    std::vector<Range> out;
    for (const Range& r : v) {
        if (!out.empty() && r.lo <= out.back().hi) {
            if (r.hi > out.back().hi) out.back().hi = r.hi;
        } else {
            out.push_back(r);
        }
    }
    return out;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n = 0;
    if (!(std::cin >> n)) return 0;
    std::vector<Range> v(n);
    for (Range& r : v) std::cin >> r.lo >> r.hi;

    const std::vector<Range> m = merge(v);
    std::cout << m.size() << '\n';
    long long total = 0;
    for (const Range& r : m) {
        std::cout << r.lo << ' ' << r.hi << '\n';
        total += r.hi - r.lo;
    }
    std::cout << "covered " << total << '\n';
    return 0;
}
